_JS = r"""
const SNAPSHOT=JSON.parse(document.getElementById('snapshot').textContent);
const rows=SNAPSHOT.symbols||[];
const select=document.getElementById('symbolSelect');
rows.forEach((row,index)=>{const option=document.createElement('option');option.value=index;option.textContent=`${row.symbol||row.report_bundle?.symbol||'?'}${row.report_bundle?'':'（数据不可用）'}`;select.appendChild(option)});
let currentRow=null,current=null,hoverIndex=null,startIndex=0,windowSize=90,showAllObservations=false,selectedTimestamp=null,activeAssessmentId=null,activeObservationId=null,priceMarkerHits=[],ruleFilter='all';
const hiddenSeries=new Set(['ema_144','ema_169']);
let chartModel=null,chartFrame=0,chartObserversStarted=false,chartRetryTimer=0,chartRetryAttempts=0;
const palette={channel_high_20:'#38bdf8',channel_low_20:'#38bdf8',channel_high_55:'#a78bfa',channel_low_55:'#a78bfa',sma_10:'#4ade80',sma_20:'#fbbf24',ema_144:'#fb7185',ema_169:'#f97316',dif:'#4ade80',dea:'#fbbf24',adx:'#e2e8f0',plus_di:'#4ade80',minus_di:'#fb7185',atr_percentile:'#60a5fa',relative_volume:'#c084fc'};
const chartSpecs=[
  {id:'priceChart',legendId:'priceLegend',keys:['channel_high_20','channel_low_20','channel_high_55','channel_low_55','sma_10','sma_20','ema_144','ema_169'],options:{candles:true,markers:true}},
  {id:'macdChart',legendId:'macdLegend',keys:['dif','dea'],options:{}},
  {id:'trendChart',legendId:'trendLegend',keys:['adx','plus_di','minus_di'],options:{}},
  {id:'volChart',legendId:'volLegend',keys:['atr_percentile','relative_volume'],options:{transform:(key,value)=>key==='atr_percentile'?value*100:value}},
];
const zh={long:'多头',short:'空头',up:'向上',down:'向下',none:'未形成',conflict:'方向冲突',CONFLICT:'方向冲突',ready:'已就绪',unavailable:'不可用',updated:'已更新',unchanged:'数据未变化',stale:'数据过期',failed:'扫描失败',blocked:'已阻塞',not_run:'未扫描',not_triggered:'未触发',not_confirmed:'未确认',STALE_DATA:'数据过期',FRESH:'数据新鲜',normal:'正常',low:'偏低',high:'偏高',medium:'中',active:'仍在持续',recovered:'已恢复',bullish:'多头共振',bearish:'空头共振',golden_cross:'金叉',death_cross:'死叉',alignment_formed:'排列形成',grade_a_entered:'进入 A 级',turtle_20:'海龟 20 日突破',turtle_55:'海龟 55 日突破',sma_10_20:'SMA10/20',macd_12_26_9:'MACD 12/26/9',sma_alignment:'SMA 排列',ema_trend:'EMA 趋势',strategy_rating:'策略评级',strategy_rating_a:'A 级共振',trend_quality:'ADX/DMI 趋势质量',volatility:'ATR 波动状态',volume:'相对成交量',above:'上方',below:'下方',inside:'通道内',outside_below:'区间下方',outside_above:'区间上方',entry_direction:'入场方向',rating_family:'评级策略族',rating_adjustment:'评级质量调整',final_rating:'最终评级',cross_signal:'交叉信号',report_only:'报告说明',strategy_direction:'策略方向',volatility_state:'波动状态',large_price_move:'价格异动',range_expansion:'日内振幅异常',range_extreme:'日内振幅异常',gap_extreme:'开盘跳空异常',atr_percentile_extreme:'ATR 分位极端',close_confirmed_up:'收盘确认向上',close_confirmed_down:'收盘确认向下',intraday_up_unconfirmed:'盘中向上越轨，收盘未确认',intraday_down_unconfirmed:'盘中向下越轨，收盘未确认',two_sided_intraday_unconfirmed:'盘中双向越轨，收盘未确认',MA_GOLDEN_CROSS_10_20:'SMA10/20 金叉',MA_DEATH_CROSS_10_20:'SMA10/20 死叉',MACD_GOLDEN_CROSS:'MACD 金叉',MACD_DEATH_CROSS:'MACD 死叉',STRATEGY_GRADE_A_LONG:'A 级多头共振',STRATEGY_GRADE_A_SHORT:'A 级空头共振',ENTRY_DECISION_LONG:'确认做多决策',ENTRY_DECISION_SHORT:'确认做空决策',ENTRY_CONFIRMED:'入场资格已确认',ELIGIBILITY_NOT_CONFIRMED:'入场资格未确认',RISK_BLOCKED:'风险资格阻断',TREND_NO_TRIGGER:'趋势尚无突破触发',OBSERVATION_ONLY:'研究模式仅观察',DATA_BLOCKED:'数据门禁阻断',SCREENING_NOT_READY:'筛选证据未就绪',NO_EXECUTABLE_TREND:'未形成可执行趋势',GRADE_B_WAIT:'B 级等待确认',PASSED:'已通过',NOT_EVALUATED:'未评估',NOT_APPLICABLE:'不适用',BLOCKED:'已阻断'};
function esc(value){return String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function label(value){return zh[String(value)]??String(value??'不可用')}
function fmt(value,digits=4){if(value===null||value===undefined||!Number.isFinite(Number(value)))return '—';const number=Number(value);return Math.abs(number)>=1000?number.toLocaleString(undefined,{maximumFractionDigits:2}):number.toFixed(digits).replace(/0+$/,'').replace(/\.$/,'')}
function shortTime(value){return value?String(value).replace('T',' ').replace('+00:00','Z'):'—'}
function badge(value){return `<span class="badge ${value===true?'true':value===false?'false':'na'}">${value===true?'满足':value===false?'未满足':'不可用'}</span>`}
function list(items,kind=''){const values=items||[];return values.length?`<ul class="compact-list ${kind}">${values.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<span class="hover-info">无</span>'}
function entryTag(value){const klass=value==='做多'||value==='做多候选'?'entry-long':value==='做空'||value==='做空候选'?'entry-short':'no-entry';return `<span class="tag ${klass}">${esc(value||'不入场')}</span>`}
function directionTag(value){const klass=value==='long'||value==='多头'?'long':value==='short'||value==='空头'?'short':'unknown';return `<span class="tag ${klass}">${esc(label(value))}</span>`}
function maxChartStart(total){return windowSize===0?0:Math.max(0,total-windowSize)}
function clampChartStart(value,total){return Math.max(0,Math.min(maxChartStart(total),Number(value)||0))}
function chartWindowBounds(total){const start=clampChartStart(startIndex,total);const end=windowSize===0?total:Math.min(total,start+windowSize);return {start,end}}
function centeredChartStart(index,total){return windowSize===0?0:clampChartStart(index-Math.floor(windowSize/2),total)}
function syncChartControls(){const total=(current?.series||[]).length;startIndex=clampChartStart(startIndex,total);const slider=document.getElementById('rangeStart');slider.max=maxChartStart(total);slider.value=startIndex;slider.disabled=Number(slider.max)===0;document.getElementById('windowSize').value=String(windowSize);document.getElementById('showAllObservations').checked=showAllObservations}
function load(index){currentRow=rows[index]||{};current=currentRow.report_bundle||null;hoverIndex=null;selectedTimestamp=null;activeAssessmentId=null;activeObservationId=null;startIndex=maxChartStart((current?.series||[]).length);chartRetryAttempts=0;if(chartRetryTimer){clearTimeout(chartRetryTimer);chartRetryTimer=0}syncChartControls();renderAll()}
function renderAll(){renderIdentity();renderDataStatus();renderScreening();renderDecision();renderBreakouts();renderTurtleObservations();renderRules();renderIndicators();renderOtherTables();renderTechnicalDetails();renderRaw();scheduleChartRender(true)}
function renderIdentity(){const bundle=current||{};const row=currentRow||{};const pairs=[['标的',row.symbol||bundle.symbol||'—'],['合约',bundle.instrument_id||row.instrument_id||row.instrument||'—'],['周期',bundle.timeframe||row.timeframe||'D1'],['数据版本',bundle.dataset_version||row.data?.dataset_version||'—'],['报告结果',bundle.result_id||'未生成'],['扫描状态',label(row.run_status)]];document.getElementById('identity').innerHTML=pairs.map(([name,value])=>`<span class="pill">${esc(name)}：<b>${esc(value)}</b></span>`).join('')}
function renderDecision(){const target=document.getElementById('decisionPanel');if(!current){target.innerHTML=`<article class="decision"><span class="kicker">市场状态</span><h2>无法生成报告</h2><p>${esc(rowError())}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>趋势不明确</h2><p>缺少可用的完整 D1 数据。</p></article><article class="decision entry"><span class="kicker">入场方向</span><h2>不入场</h2><p>未生成结构化策略结果。</p></article>`;return}const decision=current.trend_decision_result||currentRow.trend_decision_result||currentRow.stages?.trend_decision;if(decision?.result_hash){const direction=decision.trend_direction==='LONG'?'上升趋势':decision.trend_direction==='SHORT'?'下降趋势':'趋势不明确';const entry=decision.execution_state==='ENTER_LONG'?'做多':decision.execution_state==='ENTER_SHORT'?'做空':decision.execution_state==='ENTRY_CANDIDATE_LONG'?'做多候选':decision.execution_state==='ENTRY_CANDIDATE_SHORT'?'做空候选':'不入场';const confidence=decision.confidence||{};const evidence=decision.trend_direction==='LONG'?decision.long_evidence:decision.trend_direction==='SHORT'?decision.short_evidence:decision.reverse_evidence;target.innerHTML=`<article class="decision"><span class="kicker">最终趋势 / 执行状态</span><h2>${esc(decision.decision||'WAIT')} · ${esc(decision.execution_state||'WAIT')}</h2><p>截至：${esc(shortTime(decision.as_of||current.latest_bar?.timestamp))}</p><p>${esc(decision.observation_only?'观察性结果，不执行。':String(decision.execution_state||'').startsWith('ENTRY_CANDIDATE_')?'候选入场：资格闸门尚未确认，不发送正式通知。':'正式决策结果。')}</p><p>原因码：${esc(label(decision.reason_code||'—'))}；资格状态：${esc(label(decision.eligibility_status||'—'))}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>${esc(direction)}</h2>${list(evidence||[])}</article><article class="decision entry"><span class="kicker">入场方向</span><h2>${entryTag(entry)}</h2><p>${esc(decision.conclusion||'等待结构化趋势决策。')}</p><p>策略评级：${esc(confidence.rating_grade||'—')} / ${esc(fmt(confidence.rating_score,1))} 分</p></article>`;return}const assessment=current.market_assessment||legacyMarketAssessment();target.innerHTML=`<article class="decision"><span class="kicker">市场状态</span><h2>${esc(assessment.market_status||'已生成报告')}</h2><p>截至：${esc(shortTime(assessment.as_of||current.latest_bar?.timestamp))}</p><p>数据状态：${esc(label(currentRow.run_status))}</p></article><article class="decision trend"><span class="kicker">趋势判断</span><h2>${esc(assessment.trend||'趋势不明确')}</h2>${list(assessment.trend_basis||[])}</article><article class="decision entry"><span class="kicker">入场方向</span><h2>${entryTag(assessment.entry_direction)}</h2><p>${esc(assessment.entry_reason||'报告未提供展示性入场结论。')}</p><p>策略评级：${esc(assessment.rating_grade||'—')} / ${esc(fmt(assessment.rating_score,1))} 分</p></article>`}
function legacyMarketAssessment(){const rating=current.strategy_snapshot?.strategy_checks?.rating||{};return {market_status:'旧版快照：仅可展示原始策略结果',trend:'趋势不明确',trend_basis:['该快照未包含结构化突破评估。'],entry_direction:'不入场',entry_reason:'请重新运行日报以生成结构化突破与入场判断。',rating_grade:rating.grade,rating_score:rating.score}}
function rowError(){const update=currentRow?.update||{};const detail=String(update.error||currentRow?.scan?.reason||'');if(!detail)return '当前标的没有可用于生成 ReportBundle 的数据。';if(detail.includes('no current dataset'))return `未找到当前 D1 数据集（${detail}）`;if(detail.includes('update_failed_no_current'))return '数据更新失败，且没有可用的历史数据集。';return `数据处理异常：${detail}`}
function renderDataStatus(){const target=document.getElementById('dataStatusPanel');const result=current?.data_update_result||currentRow?.data_update_result||currentRow?.stages?.data_update;if(result?.result_hash){const fresh=result.freshness||{};const quality=result.quality||{};const blockers=result.blocking_reasons||[];target.innerHTML=`<b>数据状态与就绪性：</b>${esc(result.data_readiness||'BLOCKED')}；最新完整 D1：${esc(shortTime(result.latest_complete_d1))}；质量：${esc((quality.statuses||[]).join('、')||'不可用')}；新鲜度：${esc(label(fresh.status))}；血缘：${result.lineage?.verified?'已验证':'未验证'}。${blockers.length?` 阻断原因：${esc(blockers.join('、'))}。`:''}`;return}if(!current){target.innerHTML=`<b>数据与异常说明：</b>${esc(rowError())}`;return}const fresh=currentRow.freshness||{};const update=currentRow.update||{};target.innerHTML=`<b>数据状态与就绪性：</b>${esc(label(currentRow.run_status))}；最新完整 K 线：${esc(shortTime(current.latest_bar?.timestamp||currentRow.data?.latest_complete_bar))}；新鲜度：${esc(label(fresh.status))}；更新状态：${esc(label(update.status||update.mode))}。`}
function renderScreening(){const target=document.getElementById('screeningPanel');const result=current?.strategy_screening_result||currentRow?.strategy_screening_result||currentRow?.stages?.strategy_screening;if(result?.result_hash){const eligibility=result.eligibility||{};target.innerHTML=`<b>策略筛选：</b>${esc(result.screening_status||'NOT_RUN')}；条件 ${esc((result.conditions||[]).length)} 项；规则 ${esc((result.rules||[]).length)} 项；原始事件 ${esc((result.raw_events||[]).length)} 个；海龟候选突破 ${esc((result.turtle_breakouts||[]).length)} 个；资格校验：${esc(eligibility.status||'NOT_EVALUATED')}。${result.reason?` ${esc(result.reason)}`:''}`;return}target.innerHTML='<b>策略筛选：</b>旧快照兼容展示；未包含独立阶段结果。'}
function renderBreakouts(){const target=document.getElementById('breakoutRows');if(!current){target.innerHTML='<tr><td colspan="13">该标的未生成结构化报告，无法展示突破判断。</td></tr>';return}const items=current.breakout_assessments||[];if(!items.length){target.innerHTML='<tr><td colspan="13">本次扫描或回放未检测到收盘确认型海龟 20/55 日突破。</td></tr>';return}target.innerHTML=items.map(item=>`<tr id="breakout-${esc(item.assessment_id)}" class="${item.assessment_id===activeAssessmentId?'selected':''}"><td>${esc(shortTime(item.timestamp))}</td><td>${fmt(item.current_price,2)}</td><td>${esc(item.breakout_type)}</td><td>${esc(item.breakout_object)}<br><small>参考位：${fmt(item.breakout_level,2)}</small></td><td>${esc(item.previous_state)}</td><td>${esc(item.post_state)}</td><td>${esc(item.trend)}${list(item.trend_basis||[])}</td><td>${entryTag(item.entry_direction)}</td><td>${esc(item.signal_strength)}</td><td>${list(item.triggered_conditions,'ok')}</td><td>${list([...(item.unmet_conditions||[]),...(item.quality_notes||[])],'warn')}</td><td>${esc(item.conclusion)}</td><td><button type="button" data-assessment="${esc(item.assessment_id)}">定位图表</button></td></tr>`).join('');target.querySelectorAll('button[data-assessment]').forEach(button=>button.addEventListener('click',()=>focusAssessment(button.dataset.assessment,'table')))}
function focusChartItem(kind,id,origin='table'){if(!current)return;const isAssessment=kind==='assessment';const items=isAssessment?(current.breakout_assessments||[]):(current.turtle_observations||[]);const idKey=isAssessment?'assessment_id':'observation_id';const item=items.find(value=>value[idKey]===id);if(!item)return;if(isAssessment){activeAssessmentId=id;activeObservationId=null}else{activeObservationId=id;activeAssessmentId=null}selectedTimestamp=String(item.timestamp);const series=current.series||[];const index=series.findIndex(value=>String(value.timestamp)===selectedTimestamp);if(index>=0){if(windowSize===0)windowSize=90;startIndex=centeredChartStart(index,series.length);hoverIndex=index-startIndex}syncChartControls();renderBreakouts();renderTurtleObservations();scheduleChartRender(true);requestAnimationFrame(()=>{if(origin==='chart'){document.getElementById(`${isAssessment?'breakout':'observation'}-${id}`)?.scrollIntoView({behavior:'smooth',block:'center'})}else{document.getElementById('chartPanel')?.scrollIntoView({behavior:'smooth',block:'start'})}})}
function focusAssessment(id,origin='table'){focusChartItem('assessment',id,origin)}
function turtleObservationRows(){const all=current?.turtle_observations||[];const crossed=all.filter(item=>!['inside','unavailable'].includes(item.status));if(crossed.length)return crossed;const latest=new Map();for(const item of all)latest.set(item.period,item);return [...latest.values()]}
function observationExplanation(item){if(item.status==='inside')return '盘中与收盘均位于通道内。';if(item.status==='unavailable')return '通道仍在预热，无法判断。';if(item.close_confirmation==='up'||item.close_confirmation==='down')return '已满足正式收盘确认条件。';return `盘中${(item.intraday_directions||[]).map(label).join('、')}越轨，但收盘回到通道内。`}
function renderTurtleObservations(){const target=document.getElementById('turtleObservationRows');if(!current){target.innerHTML='<tr><td colspan="9">该标的没有可展示的海龟观察。</td></tr>';return}const items=turtleObservationRows();target.innerHTML=items.map(item=>`<tr id="observation-${esc(item.observation_id)}" class="${item.observation_id===activeObservationId?'selected':''}"><td>${esc(shortTime(item.timestamp))}</td><td>${esc(item.period)} 日</td><td>${esc(label(item.status))}</td><td>高 ${fmt(item.high,2)}<br>低 ${fmt(item.low,2)}</td><td>上 ${fmt(item.channel_high,2)}<br>下 ${fmt(item.channel_low,2)}</td><td>${fmt(item.close,2)}</td><td>上 ${fmt((item.upper_excess_pct??0)*100,3)}%<br>下 ${fmt((item.lower_excess_pct??0)*100,3)}%</td><td>${esc(observationExplanation(item))}</td><td><button type="button" data-observation="${esc(item.observation_id)}">定位图表</button></td></tr>`).join('')||'<tr><td colspan="9">当前可视范围没有海龟通道数据。</td></tr>';target.querySelectorAll('button[data-observation]').forEach(button=>button.addEventListener('click',()=>focusObservation(button.dataset.observation,'table')))}
function focusObservation(id,origin='table'){focusChartItem('observation',id,origin)}
function renderRules(){const target=document.getElementById('ruleList');if(!current){target.innerHTML='<div class="hover-info">没有可展示的条件明细。</div>';document.getElementById('conditionStats').textContent='';return}const allRules=current.rule_evaluations||[];const rules=ruleFilter==='unmet'?allRules.filter(rule=>!rule.triggered):allRules;let passed=0,failed=0,unavailable=0;for(const rule of allRules)for(const condition of(rule.conditions||[])){if(condition.passed===true)passed++;else if(condition.passed===false)failed++;else unavailable++}const triggered=allRules.filter(rule=>rule.triggered).length;document.getElementById('conditionStats').textContent=`规则：触发 ${triggered} / ${allRules.length}；条件：满足 ${passed} · 未满足 ${failed} · 不可用 ${unavailable}`;target.innerHTML=rules.map(rule=>{const isTurtle=String(rule.rule_id||'').startsWith('turtle_');const open=rule.triggered||isTurtle;return `<details class="rule" data-triggered="${rule.triggered}" ${open?'open':''}><summary>${badge(rule.triggered)}<span class="rule-title">${esc(ruleTitle(rule))}</span><span class="hover-info rule-state">状态：${esc(label(rule.direction||rule.outcome))}</span></summary>${turtleRuleEvidence(rule)}<div class="conditions"><table><thead><tr><th>条件</th><th>实际值</th><th>阈值/对象</th><th>运算</th><th>结果</th><th>相对位置</th><th>影响/权重</th><th>时间</th><th>价格</th></tr></thead><tbody>${(rule.conditions||[]).map(condition=>`<tr><td>${esc(conditionTitle(condition))}</td><td>${esc(fmtAny(condition.actual_value))}</td><td>${esc(fmtAny(condition.reference_value))}</td><td><code>${esc(condition.operator)}</code></td><td>${badge(condition.passed)}</td><td>${esc(label(condition.relative_position))}</td><td>${esc(label(condition.impact))} / ${fmt(condition.weight,2)}</td><td>${esc(shortTime(condition.timestamp))}</td><td>${fmt(condition.price,2)}</td></tr>`).join('')||'<tr><td colspan="9">该规则没有条件证据。</td></tr>'}</tbody></table></div></details>`}).join('')||'<div class="hover-info">没有符合筛选条件的规则。</div>'}
function setRuleView(view){if(view==='unmet'||view==='all'){ruleFilter=view;renderRules();return}document.querySelectorAll('#ruleList details.rule').forEach(item=>item.open=view==='open')}
function fmtAny(value){if(Array.isArray(value))return '['+value.map(fmtAny).join(', ')+']';if(value&&typeof value==='object')return JSON.stringify(value);return typeof value==='number'?fmt(value):String(value??'—')}
function turtleRuleEvidence(rule){const match=String(rule.rule_id||'').match(/^turtle_(20|55)_breakout$/);if(!match)return '';const period=Number(match[1]);const timestamp=rule.timestamp||(rule.conditions||[])[0]?.timestamp||current?.latest_bar?.timestamp;const item=(current?.turtle_observations||[]).find(value=>Number(value.period)===period&&String(value.timestamp)===String(timestamp))||(current?.turtle_observations||[]).filter(value=>Number(value.period)===period).at(-1);if(!item)return `<div class="rule-evidence">口径：通道取当前 K 线之前 ${period} 根完整 D1 K 线（不含当前 K 线）；正式触发必须满足收盘价严格高于上轨或严格低于下轨。当前报告没有可关联的观察证据。</div>`;return `<div class="rule-evidence"><b>收盘确认口径：</b>通道取当前 K 线之前 ${period} 根完整 D1 K 线（不含当前 K 线）；正式触发为 <code>close &gt; 上轨</code> 或 <code>close &lt; 下轨</code>，等于通道不触发。<br><b>本根证据：</b>最高 ${fmt(item.high,2)}；最低 ${fmt(item.low,2)}；收盘 ${fmt(item.close,2)}；上轨 ${fmt(item.channel_high,2)}；下轨 ${fmt(item.channel_low,2)}；盘中状态：${esc(label(item.status))}。high/low 越轨但 close 回到通道内时仅记为观察，不进入正式信号。</div>`}
function ruleTitle(rule){const titles={turtle_20_breakout:'收盘确认型海龟 20 日突破',turtle_55_breakout:'收盘确认型海龟 55 日突破',sma_10_20_golden_cross:'SMA10/20 金叉',sma_10_20_death_cross:'SMA10/20 死叉',sma_alignment_long:'SMA 多头排列',sma_alignment_short:'SMA 空头排列',ema_trend_long:'EMA 多头趋势',ema_trend_short:'EMA 空头趋势',trend_quality_confirmed:'ADX/DMI 趋势强度确认',atr_normal_range:'ATR 正常波动区间',relative_volume_confirmation:'相对成交量确认',strategy_rating_a:'策略 A 级共振'};if(titles[rule.rule_id])return titles[rule.rule_id];const match=String(rule.rule_id||'').match(/^macd_(D\d+)_(long|short)$/);return match?`${match[1]} MACD ${match[2]==='long'?'多头':'空头'}状态`:label(rule.rule_id||rule.name)}
function conditionTitle(condition){const id=String(condition.condition_id||'');const turtle=id.match(/^turtle_(20|55)\.close_(above_high|below_low)$/);if(turtle)return `收盘价${turtle[2]==='above_high'?'高于':'低于'} ${turtle[1]} 日唐奇安${turtle[2]==='above_high'?'上轨':'下轨'}`;const stack=id.match(/^sma_stack\.(\d+)_(above|below)_(\d+)$/);if(stack)return `SMA${stack[1]} ${stack[2]==='above'?'高于':'低于'} SMA${stack[3]}`;const macd=id.match(/^macd_(D\d+)\.dif_(above|below)_dea$/);if(macd)return `${macd[1]} MACD DIF ${macd[2]==='above'?'高于':'低于'} DEA`;const titles={'sma_cross.current_fast_above_slow':'当前 SMA10 高于 SMA20','sma_cross.previous_fast_not_above_slow':'前一日 SMA10 不高于 SMA20','sma_cross.current_fast_below_slow':'当前 SMA10 低于 SMA20','sma_cross.previous_fast_not_below_slow':'前一日 SMA10 不低于 SMA20','ema_trend.fast_above_slow':'EMA 快线高于慢线','ema_trend.fast_below_slow':'EMA 快线低于慢线','trend_quality.adx_threshold':'ADX 达到趋势确认阈值','volatility.atr_percentile_normal':'ATR 分位处于正常区间','volume.relative_confirmation':'相对成交量达到确认阈值','rating_a.aligned_families':'同向策略族数达到 A 级要求','rating_a.score':'综合评分达到 A 级要求'};return titles[id]||label(condition.name||id)}
function renderIndicators(){const target=document.getElementById('indicatorRows');if(!current){target.innerHTML='<tr><td colspan="6">无指标数据。</td></tr>';return}const checks=current.strategy_snapshot?.strategy_checks||{};const rows=[];const add=(name,value,detail,{direction=true}={})=>{if(value&&typeof value==='object')rows.push(`<tr><td>${esc(name)}</td><td>${esc(label(value.status||value.grade))}</td><td>${direction?directionTag(value.direction):'<span class="hover-info">不适用</span>'}</td><td>—</td><td>—</td><td>${esc(detail(value))}</td></tr>`)};add('SMA 均线排列',checks.sma_alignment,value=>`要求全部均线严格同向排列；周期 ${(value.periods||[]).join('/')}；${Object.entries(value.values||{}).map(([key,item])=>`SMA${key}=${fmt(item,2)}`).join('，')}`);add('EMA 长周期趋势',checks.ema_trend,value=>`以快线和慢线相对位置判断；周期 ${(value.periods||[]).join('/')}；${Object.entries(value.values||{}).map(([key,item])=>`EMA${key}=${fmt(item,2)}`).join('，')}`);if(checks.macd_summary)rows.push(`<tr><td>MACD 多周期零轴共识</td><td>${esc(label(checks.macd_summary.status))}</td><td>${directionTag(checks.macd_summary.direction)}</td><td>${directionTag(checks.macd_summary.direction)}</td><td>不适用</td><td>${esc(`评级依据各周期 DIF/DEA 所在零轴区域；活跃周期：${(checks.macd_summary.active_timeframes||[]).join('、')||'无'}`)}</td></tr>`);Object.entries(checks.macd||{}).forEach(([timeframe,value])=>{if(value&&typeof value==='object'){const event=value.event?label(value.event):(value.cross_status==='unavailable'?'交叉数据未就绪':'本周期无新交叉');const semantic=value.direction==='long'&&value.zero_axis==='short'?'动量向上，但 DIF/DEA 仍在零轴下方':value.direction==='short'&&value.zero_axis==='long'?'动量向下，但 DIF/DEA 仍在零轴上方':`DIF 相对 DEA 为${label(value.direction)}`;rows.push(`<tr><td>${esc(timeframe+' MACD')}</td><td>${esc(label(value.status))}</td><td>${directionTag(value.direction)}</td><td>${directionTag(value.zero_axis)}</td><td>${esc(event)}</td><td>${esc(`DIF=${fmt(value.dif)}，DEA=${fmt(value.dea)}；${semantic}`)}</td></tr>`)}});add('ADX/DMI 趋势质量',checks.trend_quality,value=>`方向由 +DI 与 -DI 判断；ADX=${fmt(value.adx,2)}，+DI=${fmt(value.plus_di,2)}，-DI=${fmt(value.minus_di,2)}；趋势强度${value.confirmed?'已达到':'未达到'}阈值`);add('ATR 波动状态',checks.volatility,value=>`无多空方向；ATR=${fmt(value.atr,4)}，ATR%=${fmt((value.atr_pct??0)*100,2)}%，120 日分位=${fmt((value.percentile??0)*100,1)}%`,{direction:false});add('相对成交量',checks.volume,value=>`无多空方向；相对量=${fmt(value.relative_volume,2)}，前置基准=${fmt(value.baseline,2)}；${value.confirmed?'达到':'未达到'}确认阈值`,{direction:false});add('组合评级',checks.rating,value=>`${value.direction==='conflict'&&Number(value.score)===0?'方向冲突门控，未计分':'评分 '+fmt(value.score,1)}；策略族：${Object.entries(value.family_votes||{}).map(([key,item])=>`${label(key)}=${label(item)}`).join('，')}`);target.innerHTML=rows.join('')||'<tr><td colspan="6">指标仍在预热或不可用。</td></tr>'}
function isTurtleSignal(signal){const name=String(signal.indicator_name||signal.indicator||'');const type=String(signal.signal_type||'');return name==='turtle_20'||name==='turtle_55'||type.startsWith('TURTLE_')}
function signalName(signal){const name=signal.indicator_name||signal.indicator||signal.signal_type||signal.event;const event=signal.event||signal.signal_type;return `${label(name)}${event?`：${label(event)}`:''}`}
function renderOtherTables(){const signals=(current?.signals||[]).filter(signal=>!isTurtleSignal(signal));document.getElementById('signalRows').innerHTML=signals.map(signal=>`<tr><td>${esc(shortTime(signal.signal_time||signal.timestamp))}</td><td>${esc(signalName(signal))}</td><td>${directionTag(String(signal.direction||'').toLowerCase())}</td><td>${fmt(signal.trigger_price??signal.price,2)}</td></tr>`).join('')||'<tr><td colspan="4">本次没有均线或 MACD 事件。</td></tr>';const episodes=current?.anomaly_episodes||[];document.getElementById('anomalyEpisodeRows').innerHTML=episodes.map(item=>`<tr><td>${esc(shortTime(item.start_timestamp))}<br>至 ${esc(shortTime(item.end_timestamp))}</td><td>${esc(label(item.anomaly_type))}${item.side!=='none'?`（${esc(label(item.side))}）`:''}</td><td>${esc(label(item.severity))}</td><td>${esc(label(item.status))}</td><td>${esc(item.duration_bars)} 根</td><td>${fmtAny(item.extreme_actual)} / ${esc(fmtAny(item.reference_value))}<br><small>${esc(item.summary)}</small></td></tr>`).join('')||'<tr><td colspan="6">当前可视范围没有异常阶段。</td></tr>';const anomalies=current?.anomalies||[];document.getElementById('anomalyRows').innerHTML=anomalies.map(item=>`<tr><td>${esc(shortTime(item.timestamp))}</td><td>${esc(label(item.anomaly_type))}</td><td>${esc(label(item.severity))}</td><td>${esc(anomalySummary(item))}</td></tr>`).join('')||'<tr><td colspan="4">当前可视范围没有逐日异常点。</td></tr>'}
function anomalySummary(item){const condition=(item.conditions||[])[0];const titles={large_price_move:'单日价格变动超过阈值',range_expansion:'单日高低价振幅异常扩大',range_extreme:'单日高低价振幅超过 3×ATR',gap_extreme:'开盘相对前收跳空超过 2×ATR',atr_percentile_extreme:'120 日 ATR 排名低于 2% 或高于 98%'};const base=titles[item.anomaly_type]||item.summary||label(item.anomaly_type);return condition?`${base}；实际 ${fmtAny(condition.actual_value)}，阈值 ${fmtAny(condition.reference_value)}`:base}
function renderTechnicalDetails(){const transitions=current?.state_transitions||[];document.getElementById('transitionRows').innerHTML=transitions.map(item=>`<tr><td>${esc(shortTime(item.timestamp))}</td><td>${esc(label(item.state_name))}</td><td>${esc(label(item.from_state))}</td><td>${esc(label(item.to_state))}</td><td>${esc(`${label(item.state_name)}从 ${label(item.from_state)} 变为 ${label(item.to_state)}`)}</td></tr>`).join('')||'<tr><td colspan="5">当前可视范围未发生监控状态变更。</td></tr>';const changes=current?.change_log||[];document.getElementById('changeRows').innerHTML=changes.map(item=>`<tr><td><code>${esc(item.module)}</code></td><td>${esc(item.change)}</td><td>${esc(item.reason)}</td><td>${esc(item.effect)}</td></tr>`).join('')||'<tr><td colspan="4">无技术说明。</td></tr>'}
function renderRaw(){document.getElementById('rawJson').textContent=JSON.stringify(currentRow||{},null,2)}
function legend(id,items){document.getElementById(id).innerHTML=items.map(item=>`<button type="button" data-series="${esc(item)}" aria-pressed="${hiddenSeries.has(item)?'false':'true'}" title="点击显示或隐藏"><i style="background:${palette[item]||'#fff'}"></i>${esc(legendName(item))}</button>`).join('')}
function legendName(item){return {channel_high_20:'20 日上轨',channel_low_20:'20 日下轨',channel_high_55:'55 日上轨',channel_low_55:'55 日下轨',sma_10:'SMA10',sma_20:'SMA20',ema_144:'EMA144',ema_169:'EMA169',dif:'DIF',dea:'DEA',adx:'ADX',plus_di:'+DI',minus_di:'-DI',atr_percentile:'ATR 分位',relative_volume:'相对成交量'}[item]||item}
function setupCanvas(id){const canvas=document.getElementById(id);if(!canvas||!canvas.isConnected)return null;const width=Math.floor(canvas.clientWidth),height=Math.floor(canvas.clientHeight);if(width<2||height<2||canvas.getClientRects().length===0)return null;const dpr=Math.max(1,Math.min(3,window.devicePixelRatio||1));const pixelWidth=Math.max(1,Math.round(width*dpr)),pixelHeight=Math.max(1,Math.round(height*dpr));if(canvas.width!==pixelWidth||canvas.height!==pixelHeight){canvas.width=pixelWidth;canvas.height=pixelHeight}const context=canvas.getContext('2d');if(!context)return null;context.setTransform(dpr,0,0,dpr,0,0);return {canvas,context,width,height}}
function chartExtent(chartRows,keys,options){const values=[];for(const row of chartRows)for(const key of keys){if(hiddenSeries.has(key))continue;const value=row[key];if(value!==null&&Number.isFinite(Number(value)))values.push(options.transform?options.transform(key,Number(value)):Number(value))}if(options.candles)for(const row of chartRows)for(const key of ['open','high','low','close'])if(Number.isFinite(Number(row[key])))values.push(Number(row[key]));if(!values.length)return null;let min=Math.min(...values),max=Math.max(...values);if(min===max){min-=1;max+=1}const span=max-min;return {min:min-span*.06,max:max+span*.06}}
function rebuildChartModel(){const series=current?.series||[];const {start,end}=chartWindowBounds(series.length);startIndex=start;const chartRows=series.slice(start,end);chartModel={absoluteStart:start,rows:chartRows,charts:chartSpecs.map(spec=>({...spec,extent:chartExtent(chartRows,spec.keys,spec.options)}))};syncChartControls();const range=document.getElementById('rangeLabel');range.textContent=chartRows.length?`${shortTime(chartRows[0].timestamp)} 至 ${shortTime(chartRows[chartRows.length-1].timestamp)}（${chartRows.length} 根）`:'无图表数据';for(const spec of chartSpecs)legend(spec.legendId,spec.keys);if(hoverIndex!==null&&!chartRows[hoverIndex])hoverIndex=null;return chartModel}
function renderCharts(){scheduleChartRender(false)}
function scheduleChartRender(rebuild=false){if(rebuild)chartModel=null;if(chartFrame)return;chartFrame=requestAnimationFrame(()=>{chartFrame=0;paintCharts()})}
function paintCharts(){const model=chartModel||rebuildChartModel();priceMarkerHits=[];let painted=false;for(const spec of model.charts)painted=draw(spec,model.rows)||painted;updateHoverInfo(model.rows);if(painted){chartRetryAttempts=0;if(chartRetryTimer){clearTimeout(chartRetryTimer);chartRetryTimer=0}}else if(chartRetryAttempts<8&&!chartRetryTimer){chartRetryAttempts++;chartRetryTimer=setTimeout(()=>{chartRetryTimer=0;scheduleChartRender(false)},80)}return painted}
function updateHoverInfo(chartRows){if(hoverIndex!==null&&chartRows[hoverIndex]){const row=chartRows[hoverIndex];const observations=(current?.turtle_observations||[]).filter(item=>String(item.timestamp)===String(row.timestamp)&&!['inside','unavailable'].includes(item.status));const turtle=observations.length?` · 海龟 ${observations.map(item=>`${item.period}日${label(item.status)}`).join('、')}`:'';document.getElementById('hoverInfo').textContent=`${shortTime(row.timestamp)} · 开 ${fmt(row.open,2)} · 高 ${fmt(row.high,2)} · 低 ${fmt(row.low,2)} · 收 ${fmt(row.close,2)} · ADX ${fmt(row.adx,2)} · ATR 分位 ${fmt((row.atr_percentile??0)*100,1)}% · 相对成交量 ${fmt(row.relative_volume,2)}${turtle}`}else document.getElementById('hoverInfo').textContent='移动鼠标查看 OHLC 与同一时间点指标；实心三角为正式突破，空心琥珀点为盘中越轨。'}
function lineStyle(key){if(key.includes('_55'))return {width:1.25,alpha:.78,dash:[6,4]};if(key.includes('channel_'))return {width:1.25,alpha:.82,dash:[]};if(key.startsWith('sma_')||key.startsWith('ema_'))return {width:1,alpha:.65,dash:[]};return {width:1.35,alpha:.9,dash:[]}}
function axisDate(value){const text=String(value||'');return text.slice(5,10)||text}
function draw(spec,chartRows){
  const surface=setupCanvas(spec.id);if(!surface)return false;
  const {context,width,height}=surface,{keys,options,extent}=spec;
  context.clearRect(0,0,width,height);const pad={left:72,right:18,top:16,bottom:34};context.font='11px system-ui';
  if(!extent){context.fillStyle='#8095aa';context.fillText('数据不足',pad.left,pad.top+16);return true}
  const {min,max}=extent,innerWidth=Math.max(1,width-pad.left-pad.right),innerHeight=Math.max(1,height-pad.top-pad.bottom),slot=innerWidth/Math.max(1,chartRows.length);
  const x=index=>pad.left+(index+.5)*slot,y=value=>pad.top+(max-value)/(max-min)*innerHeight;
  for(let line=0;line<5;line++){const yy=pad.top+line*innerHeight/4;context.strokeStyle='#172a3d';context.lineWidth=1;context.beginPath();context.moveTo(pad.left,yy);context.lineTo(width-pad.right,yy);context.stroke();context.fillStyle='#8095aa';context.textAlign='right';context.fillText(fmt(max-line*(max-min)/4,2),pad.left-8,yy+4)}
  const dateStep=Math.max(1,Math.ceil(chartRows.length/6));context.textAlign='center';for(let index=0;index<chartRows.length;index+=dateStep){const xx=x(index);context.strokeStyle='#102337';context.beginPath();context.moveTo(xx,pad.top);context.lineTo(xx,height-pad.bottom);context.stroke();context.fillStyle='#71879d';context.fillText(axisDate(chartRows[index].timestamp),xx,height-10)}
  if(options.candles){const body=Math.max(2,Math.min(12,slot*.68));chartRows.forEach((row,index)=>{const open=Number(row.open),high=Number(row.high),low=Number(row.low),close=Number(row.close);if(![open,high,low,close].every(Number.isFinite))return;const rising=close>=open,color=rising?'#22c55e':'#ef4444',xx=x(index),openY=y(open),closeY=y(close);context.strokeStyle=color;context.fillStyle=color;context.lineWidth=1.2;context.beginPath();context.moveTo(xx,y(high));context.lineTo(xx,y(low));context.stroke();const top=Math.min(openY,closeY),bodyHeight=Math.abs(openY-closeY);if(bodyHeight<1.4){context.beginPath();context.moveTo(xx-body/2,top);context.lineTo(xx+body/2,top);context.stroke()}else if(rising){context.globalAlpha=.2;context.fillRect(xx-body/2,top,body,bodyHeight);context.globalAlpha=1;context.strokeRect(xx-body/2,top,body,bodyHeight)}else context.fillRect(xx-body/2,top,body,bodyHeight)})}
  for(const key of keys){if(hiddenSeries.has(key))continue;const style=lineStyle(key);context.strokeStyle=palette[key]||'#fff';context.lineWidth=style.width;context.globalAlpha=style.alpha;context.setLineDash(style.dash);context.beginPath();let started=false;chartRows.forEach((row,index)=>{let value=row[key];if(value===null||!Number.isFinite(Number(value))){started=false;return}value=options.transform?options.transform(key,Number(value)):Number(value);if(!started){context.moveTo(x(index),y(value));started=true}else context.lineTo(x(index),y(value))});context.stroke();context.globalAlpha=1;context.setLineDash([])}
  if(options.markers){drawMarkers(context,chartRows,x,y);drawAnomalies(context,chartRows,x,y)}
  if(hoverIndex!==null&&chartRows[hoverIndex]){const row=chartRows[hoverIndex],yy=options.candles&&Number.isFinite(Number(row.close))?y(Number(row.close)):null;context.strokeStyle='#94a3b8';context.lineWidth=1;context.setLineDash([3,4]);context.beginPath();context.moveTo(x(hoverIndex),pad.top);context.lineTo(x(hoverIndex),height-pad.bottom);if(yy!==null){context.moveTo(pad.left,yy);context.lineTo(width-pad.right,yy)}context.stroke();context.setLineDash([])}
  context.textAlign='left';return true
}
function drawMarkers(context,chartRows,x,y){const byTime=new Map(chartRows.map((row,index)=>[String(row.timestamp),index]));for(const item of(current?.breakout_assessments||[])){const index=byTime.get(String(item.timestamp));if(index===undefined)continue;const price=Number(item.current_price??chartRows[index].close);if(!Number.isFinite(price))continue;const xx=x(index),yy=y(price),color=item.entry_direction==='做多'?'#4ade80':item.entry_direction==='做空'?'#fb7185':'#fbbf24';context.fillStyle=color;context.strokeStyle=item.assessment_id===activeAssessmentId?'#e2e8f0':color;context.lineWidth=item.assessment_id===activeAssessmentId?2:1;context.beginPath();if(item.breakout_type==='向下突破'){context.moveTo(xx,yy+7);context.lineTo(xx-6,yy-5);context.lineTo(xx+6,yy-5)}else{context.moveTo(xx,yy-7);context.lineTo(xx-6,yy+5);context.lineTo(xx+6,yy+5)}context.closePath();context.fill();context.stroke();priceMarkerHits.push({kind:'assessment',id:item.assessment_id,x:xx,y:yy})}const candidates=(current?.turtle_observations||[]).filter(item=>!['inside','unavailable'].includes(item.status)&&(showAllObservations||item.observation_id===activeObservationId));const groups=new Map();for(const item of candidates)for(const direction of(item.intraday_directions||[])){const key=`${item.timestamp}|${direction}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)}for(const [key,items] of groups){const [timestamp,direction]=key.split('|');const index=byTime.get(timestamp);if(index===undefined)continue;const prices=items.map(item=>Number(direction==='up'?item.high:item.low)).filter(Number.isFinite);if(!prices.length)continue;const price=direction==='up'?Math.max(...prices):Math.min(...prices),xx=x(index),yy=y(price),active=items.some(item=>item.observation_id===activeObservationId),radius=active?7:3;context.fillStyle='#08131f';context.strokeStyle=active?'#f8fafc':'#fbbf24';context.lineWidth=active?3:1.5;context.beginPath();context.arc(xx,yy,radius,0,Math.PI*2);context.fill();context.stroke();if(active){context.fillStyle='#fbbf24';context.font='11px system-ui';context.fillText(items.map(item=>item.period).join('/'),xx+9,yy-7)}priceMarkerHits.push({kind:'observation',id:(items.find(item=>item.observation_id===activeObservationId)||items[0]).observation_id,x:xx,y:yy})}}
function drawAnomalies(context,chartRows,x,y){const byTime=new Map(chartRows.map((row,index)=>[String(row.timestamp),index]));for(const item of(current?.anomalies||[])){const index=byTime.get(String(item.timestamp));if(index===undefined)continue;const price=Number(item.price??chartRows[index].close);if(!Number.isFinite(price))continue;context.fillStyle='#60a5fa';context.fillRect(x(index)-3,y(price)-3,6,6)}}
function pointerPosition(event,canvas){const rect=canvas.getBoundingClientRect();return {x:(event.clientX-rect.left)*(canvas.clientWidth/Math.max(1,rect.width)),y:(event.clientY-rect.top)*(canvas.clientHeight/Math.max(1,rect.height))}}
function handleChartPointer(event){const chartRows=(chartModel||rebuildChartModel()).rows;if(!chartRows.length)return;const canvas=event.currentTarget;const point=pointerPosition(event,canvas);const pad={left:72,right:18};const innerWidth=Math.max(1,canvas.clientWidth-pad.left-pad.right),slot=innerWidth/Math.max(1,chartRows.length);const index=Math.max(0,Math.min(chartRows.length-1,Math.floor((point.x-pad.left)/slot)));if(index!==hoverIndex){hoverIndex=index;scheduleChartRender(false)}}
function clearChartPointer(){if(hoverIndex!==null){hoverIndex=null;scheduleChartRender(false)}}
function handlePriceClick(event){const point=pointerPosition(event,event.currentTarget);const hit=priceMarkerHits.find(marker=>Math.hypot(point.x-marker.x,point.y-marker.y)<12);if(!hit)return;if(hit.kind==='assessment')focusAssessment(hit.id,'chart');else focusObservation(hit.id,'chart')}
function initializeCharts(){if(chartObserversStarted)return;chartObserversStarted=true;for(const spec of chartSpecs){const canvas=document.getElementById(spec.id);canvas.addEventListener('pointermove',handleChartPointer,{passive:true});canvas.addEventListener('pointerleave',clearChartPointer,{passive:true})}document.getElementById('priceChart').addEventListener('click',handlePriceClick);const requestReflow=()=>scheduleChartRender(false);window.addEventListener('resize',requestReflow,{passive:true});window.addEventListener('pageshow',requestReflow);document.addEventListener('visibilitychange',()=>{if(!document.hidden)requestReflow()});document.addEventListener('toggle',requestReflow,true);document.addEventListener('transitionend',requestReflow,true);if('ResizeObserver'in window){const observer=new ResizeObserver(requestReflow);observer.observe(document.getElementById('chartPanel'));for(const spec of chartSpecs)observer.observe(document.getElementById(spec.id))}if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))requestReflow()});observer.observe(document.getElementById('chartPanel'))}if('MutationObserver'in window){const observer=new MutationObserver(requestReflow);observer.observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:['class','style','hidden','open','aria-hidden','aria-expanded','aria-selected']})}document.fonts?.ready.then(requestReflow)}
select.addEventListener('change',()=>load(Number(select.value)));
document.getElementById('rangeStart').addEventListener('input',event=>{startIndex=clampChartStart(event.target.value,(current?.series||[]).length);hoverIndex=null;selectedTimestamp=null;scheduleChartRender(true)});
document.getElementById('windowSize').addEventListener('change',event=>{windowSize=Number(event.target.value);const series=current?.series||[];const selectedIndex=selectedTimestamp?series.findIndex(row=>String(row.timestamp)===selectedTimestamp):-1;startIndex=selectedIndex>=0?centeredChartStart(selectedIndex,series.length):maxChartStart(series.length);hoverIndex=selectedIndex>=0?selectedIndex-startIndex:null;syncChartControls();scheduleChartRender(true)});
document.getElementById('showAllObservations').addEventListener('change',event=>{showAllObservations=event.target.checked;scheduleChartRender(false)});
document.querySelectorAll('.legend').forEach(target=>target.addEventListener('click',event=>{const button=event.target.closest('button[data-series]');if(!button)return;const key=button.dataset.series;if(hiddenSeries.has(key))hiddenSeries.delete(key);else hiddenSeries.add(key);scheduleChartRender(true)}));
document.querySelectorAll('button[data-rule-view]').forEach(button=>button.addEventListener('click',()=>setRuleView(button.dataset.ruleView)));
initializeCharts();
if(rows.length)load(0);else{document.getElementById('identity').textContent='快照中没有可供展示的标的。';scheduleChartRender(true)}
"""


